const binaryData = items[0].binary.file;
const base64Data = binaryData.data;
const body = items[0].json.body || {};

const prompt = `You are an expert exam question creator for university level courses. Extract comprehensive open-ended exam questions and detailed step-by-step model answers from this lecture PDF.
Extract all key concepts, definitions, mathematical equations, explanations, and diagrams.
For any equations or mathematical formulas, use standard LaTeX syntax enclosed in $...$ or $$...$$.
For diagrams or visual drawings, describe the diagram context clearly within the question.

CRITICAL RULES:
1. Questions must be open-ended (essay / explanation / calculation / derivation). DO NOT create multiple-choice (MCQ) or true/false questions.
2. Return ONLY a valid, raw JSON array of objects with no markdown code blocks, backticks, or other text.

JSON Schema:
[
  {
    "question": "Clear, high-quality open-ended question text...",
    "answer": "Comprehensive model answer...",
    "type": "text"
  }
]`;

return [{
  json: {
    subject_id: body.subject_id || '0',
    subject_name: body.subject_name || '',
    lecture_number: parseInt(body.lecture_number || '1', 10),
    geminiPayload: {
      contents: [{
        parts: [
          { text: prompt },
          {
            inline_data: {
              mime_type: binaryData.mimeType || 'application/pdf',
              data: base64Data
            }
          }
        ]
      }]
    }
  }
}];

const prepData = $('Prepare Request').first().json;
const subject_id = prepData.subject_id;
const subject_name = prepData.subject_name;
const lecture_number = prepData.lecture_number;

let text = '';
try {
  text = $json.candidates[0].content.parts[0].text;
} catch (e) {
  throw new Error('Gemini did not return text response: ' + JSON.stringify($json));
}

// Strip markdown code fences if present
text = text.replace(/```json/gi, '').replace(/```/g, '').trim();

let questions = [];
try {
  questions = JSON.parse(text);
} catch (e) {
  throw new Error('Failed to parse Gemini JSON: ' + text);
}

if (!Array.isArray(questions)) {
  questions = [questions];
}

return questions.map(q => ({
  json: {
    subject_id: String(subject_id),
    subject_name: String(subject_name || ''),
    lecture_number: parseInt(lecture_number || 1, 10),
    question: q.question || '',
    answer: q.answer || '',
    type: q.type || 'text',
    used: false
  }
}));
